#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Snippet Searcher: first deployment. Everything that needs an account: GitHub, Auth0, New Relic,
# the two Azure VMs (dev and prod) with Docker Swarm, the Swarm secrets, the GitHub secrets and
# variables, and the first push. See README.md, "Despliegue (Docker Swarm)".

TOTAL_STAGES=13

INFRA=$(cd "$(dirname "$0")/.." && pwd)
ROOT=$(dirname "$INFRA")
ENV_FILE="$INFRA/.env.deploy"
touch "$ENV_FILE"; chmod 600 "$ENV_FILE"

SERVICES=(snippet-service permission-service printscript-runner)
APPS=("${SERVICES[@]}" printscript-ui)
REPOS=("${APPS[@]}" snippet-searcher-infra)
DEPLOY_KEY="$HOME/.ssh/snippet-searcher-deploy"
VM_USER=azureuser
RESOURCE_GROUP=snippet-searcher

# ask_or KEY "Prompt" DEFAULT: like ask, with a default when there is no saved value
ask_or() {
  ask "$1" "$2 [$3]"
  [[ -n "${!1}" ]] || printf -v "$1" '%s' "$3"
  write_env "$1" "${!1}"
}

# ask_saved KEY "Prompt" / ask_secret_saved: ask (or ask_secret) until non-empty, then write_env
ask_saved() {
  while :; do ask "$1" "$2"; [[ -n "${!1}" ]] && break; warn "can't be empty"; done
  write_env "$1" "${!1}"
}
ask_secret_saved() {
  while :; do ask_secret "$1" "$2"; [[ -n "${!1}" ]] && break; warn "can't be empty"; done
  write_env "$1" "${!1}"
}

# gh_secret REPO ENVIRONMENT NAME VALUE (ENVIRONMENT "" = repo secret); gh_var the same for variables
gh_secret() {
  local repo=$1 env=$2 name=$3 value=$4
  local args=(-R "$OWNER/$repo")
  [[ -n "$env" ]] && args+=(--env "$env")
  if printf '%s' "$value" | gh secret set "$name" "${args[@]}" >/dev/null; then
    WRITTEN_SECRET+=("$repo${env:+/$env}:$name")
    printf '  %s✓ set%s secret %s %s\n' "$GREEN" "$RESET" "$repo${env:+ ($env)}" "$name"
  else
    SKIPPED+=("secret $name in $repo${env:+ ($env)}")
  fi
}
gh_var() {
  local repo=$1 env=$2 name=$3 value=$4
  local args=(-R "$OWNER/$repo")
  [[ -n "$env" ]] && args+=(--env "$env")
  if gh variable set "$name" --body "$value" "${args[@]}" >/dev/null; then
    printf '  %s✓ set%s variable %s %s=%s\n' "$GREEN" "$RESET" "$repo${env:+ ($env)}" "$name" "$value"
  else
    SKIPPED+=("variable $name in $repo${env:+ ($env)}")
  fi
}

domain_of() { local label="${1^^}_DNS_LABEL"; printf '%s.%s.cloudapp.azure.com' "${!label}" "$AZURE_LOCATION"; }

banner "Snippet Searcher · first deployment"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Prerequisites"
missing=0
for cmd in git gh ssh ssh-keygen ssh-keyscan az; do
  if command -v "$cmd" >/dev/null 2>&1; then note "✓ $cmd"; else warn "missing: $cmd"; missing=1; fi
done
if (( missing )); then
  say "Install what's missing and run again. The Azure CLI without installing it:"
  say "  nix shell nixpkgs#azure-cli -c $0"
  exit 1
fi
if ! gh auth status >/dev/null 2>&1; then
  say "gh isn't logged in. Run: gh auth login   (then this script again)"
  exit 1
fi
OWNER=$(gh api user --jq .login)
write_env OWNER "$OWNER"
note "GitHub account: $OWNER"
# printscript-runner downloads PrintScript from GitHub Packages with its CI token: that works only
# while the PrintScript repo is public
if [[ "$(gh repo view "$OWNER/printscript" --json visibility --jq .visibility 2>/dev/null)" == PUBLIC ]]; then
  note "✓ $OWNER/printscript is public: printscript-runner's CI can download PrintScript"
else
  warn "$OWNER/printscript isn't public (or doesn't exist): printscript-runner's image build won't find PrintScript"
  SKIPPED+=("make $OWNER/printscript public, or give printscript-runner a token that can read its packages")
fi
pause "Press Enter to continue"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Names and domains"
say "Each VM gets a free domain from Azure: <label>.<region>.cloudapp.azure.com."
say "Let's Encrypt issues the certificate for that domain. The label must be unique in the region."
note "Azure for Students only allows some regions and sizes (az policy assignment list, az vm list-skus);"
note "for this subscription B2s was only available in northcentralus."
owner_lc=${OWNER,,}
ask_or AZURE_LOCATION "Azure region:" northcentralus
ask_or DEV_DNS_LABEL "DNS label for dev:" "snippets-dev-$owner_lc"
ask_or PROD_DNS_LABEL "DNS label for prod:" "snippets-$owner_lc"
ask_or VM_SIZE "VM size (B2s = 2 vCPU / 4 GB; B2ms = 8 GB if memory runs short):" Standard_B2s
ask_or REPO_VISIBILITY "New GitHub repos (private or public):" private
ask_or LETSENCRYPT_EMAIL "Email for Let's Encrypt (expiry notices):" "$(git config user.email || true)"
DEV_DOMAIN=$(domain_of dev); PROD_DOMAIN=$(domain_of prod)
write_env DEV_DOMAIN "$DEV_DOMAIN"; write_env PROD_DOMAIN "$PROD_DOMAIN"
say ""
say "dev:  https://$DEV_DOMAIN"
say "prod: https://$PROD_DOMAIN"
pause "Press Enter to continue"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "GitHub repositories"
say "Creates the GitHub repo of each local repo that has no remote yet (nothing is pushed until the last stage)."
for repo in "${REPOS[@]}"; do
  dir="$ROOT/$repo"
  if git -C "$dir" remote get-url origin >/dev/null 2>&1; then
    note "✓ $repo → $(git -C "$dir" remote get-url origin)"
  elif gh repo view "$OWNER/$repo" >/dev/null 2>&1; then
    git -C "$dir" remote add origin "git@github.com:$OWNER/$repo.git"
    note "✓ $repo exists on GitHub; added it as origin"
  elif confirm "Create $OWNER/$repo ($REPO_VISIBILITY)?"; then
    gh repo create "$OWNER/$repo" "--$REPO_VISIBILITY" --source "$dir" --remote origin >/dev/null
    printf '  %s✓ created%s %s\n' "$GREEN" "$RESET" "$OWNER/$repo"
  else
    SKIPPED+=("GitHub repo $OWNER/$repo")
  fi
done
pause "Press Enter to continue"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "GitHub: deploy token (DEPLOY_PAT)"
say "A classic token. The services use it to trigger snippet-searcher-infra's Deploy workflow,"
say "and the Deploy workflow uses it to pull the images from GHCR."
open_url "https://github.com/settings/tokens/new?scopes=repo,read:packages&description=snippet-searcher-deploy"
step "The page comes with the scopes repo and read:packages already ticked."
step "Expiration: one that outlasts the course (or No expiration)."
step "Generate token → copy it (it's shown only once)."
ask_secret_saved DEPLOY_PAT "Paste the token:"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Auth0: tenant and API"
say "One tenant for dev and prod. If you don't have an Auth0 account yet, sign up first (free plan)."
open_url "https://manage.auth0.com/"
step "Applications → APIs → + Create API."
step "Name: Snippet Searcher · Identifier: https://snippet-searcher/api · signing algorithm RS256 → Create."
step "In the API: Settings tab → Access Settings → turn on 'Allow Offline Access' → Save (the UI's refresh token)."
ask_or AUTH0_AUDIENCE "API Identifier:" "https://snippet-searcher/api"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Auth0: the UI application (SPA)"
step "Applications → Applications → + Create Application."
step "Name: printscript-ui · type: Single Page Web Applications → Create."
step "Settings tab. Paste this list in 'Allowed Callback URLs', 'Allowed Logout URLs' and 'Allowed Web Origins':"
say ""
say "    https://$DEV_DOMAIN, https://$PROD_DOMAIN, http://localhost:5173"
say ""
step "Further down, 'Refresh Token Rotation': turn on 'Allow Refresh Token Rotation' → Save Changes."
step "At the top of Settings, copy the Domain (like dev-xxxx.us.auth0.com) and the Client ID."
ask_saved AUTH0_DOMAIN "Domain (without https://):"
AUTH0_DOMAIN=${AUTH0_DOMAIN#https://}; AUTH0_DOMAIN=${AUTH0_DOMAIN%/}
write_env AUTH0_DOMAIN "$AUTH0_DOMAIN"
ask_saved AUTH0_SPA_CLIENT_ID "Client ID of printscript-ui:"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Auth0: the services application (M2M)"
say "One machine-to-machine app: client credentials for calls without a user, and the"
say "Management API to search users when sharing a snippet."
step "Applications → Applications → + Create Application."
step "Name: snippet-searcher-services · type: Machine to Machine Applications → Create."
step "It asks for an API to authorize: Auth0 Management API, permission read:users → Authorize."
step "In the app, APIs tab: turn on (authorize) Snippet Searcher too. It needs no permissions."
step "Settings tab: copy the Client ID and the Client Secret."
ask_saved AUTH0_M2M_CLIENT_ID "Client ID:"
ask_secret_saved AUTH0_M2M_CLIENT_SECRET "Client Secret:"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "New Relic: license key"
if confirm "Set up New Relic now? (No: it stays off and can be turned on later)"; then
  say "If you don't have an account, sign up first (free plan). The region you pick there matters."
  open_url "https://one.newrelic.com/api-keys"
  step "In the API keys list, the key of type INGEST - LICENSE → '...' → Copy key."
  ask_secret_saved NEW_RELIC_LICENSE_KEY "Paste the license key:"
  ask_or NEW_RELIC_REGION "Account region (US or EU):" US
  if [[ "${NEW_RELIC_REGION^^}" == EU ]]; then
    NEW_RELIC_OTLP_URL=https://otlp.eu01.nr-data.net/v1/metrics
  else
    NEW_RELIC_OTLP_URL=https://otlp.nr-data.net/v1/metrics
  fi
  NEW_RELIC_ENABLED=true
else
  # The Swarm secret has to exist anyway; with NEW_RELIC_ENABLED=false nobody reads it
  NEW_RELIC_LICENSE_KEY=${NEW_RELIC_LICENSE_KEY:-none}
  NEW_RELIC_OTLP_URL=https://otlp.nr-data.net/v1/metrics
  NEW_RELIC_ENABLED=false
  note "Later: run this script again and answer yes, then 'docker secret rm' the old key (see README)."
fi
write_env NEW_RELIC_LICENSE_KEY "$NEW_RELIC_LICENSE_KEY"
write_env NEW_RELIC_OTLP_URL "$NEW_RELIC_OTLP_URL"
write_env NEW_RELIC_ENABLED "$NEW_RELIC_ENABLED"

# ── 9, 10 ─────────────────────────────────────────────────────────────────
create_vm() {
  local env=$1 vm="snippet-searcher-$1" label="${1^^}_DNS_LABEL"
  stage "Azure: the $env VM"
  az account show >/dev/null 2>&1 || { say "Logging in to Azure (opens the browser)…"; az login >/dev/null; }
  note "Subscription: $(az account show --query name -o tsv)"
  if az vm show -g "$RESOURCE_GROUP" -n "$vm" >/dev/null 2>&1; then
    note "✓ $vm already exists"
  else
    [[ -f "$HOME/.ssh/id_ed25519.pub" ]] || ssh-keygen -t ed25519 -f "$HOME/.ssh/id_ed25519" -N "" >/dev/null
    say "Ubuntu 24.04, $VM_SIZE, user $VM_USER with your key ~/.ssh/id_ed25519.pub,"
    say "domain $(domain_of "$env"), ports 22, 80 and 443 open. It costs money while it runs."
    if ! confirm "Create $vm in $AZURE_LOCATION?"; then
      SKIPPED+=("Azure VM $vm"); return
    fi
    az group create -n "$RESOURCE_GROUP" -l "$AZURE_LOCATION" -o none
    az vm create -g "$RESOURCE_GROUP" -n "$vm" -l "$AZURE_LOCATION" \
      --image Ubuntu2404 --size "$VM_SIZE" \
      --admin-username "$VM_USER" --ssh-key-values "$HOME/.ssh/id_ed25519.pub" \
      --public-ip-sku Standard --public-ip-address-dns-name "${!label}" -o none
    az vm open-port -g "$RESOURCE_GROUP" -n "$vm" --port 80 --priority 1010 -o none
    az vm open-port -g "$RESOURCE_GROUP" -n "$vm" --port 443 --priority 1020 -o none
    printf '  %s✓ created%s %s\n' "$GREEN" "$RESET" "$vm"
  fi
  note "Public IP: $(az vm show -d -g "$RESOURCE_GROUP" -n "$vm" --query publicIps -o tsv)"
  pause "Press Enter to continue"
}
create_vm dev
create_vm prod

# ── 11 ────────────────────────────────────────────────────────────────────
stage "VMs: Docker, Swarm, deploy key and secrets"
[[ -f "$DEPLOY_KEY" ]] || ssh-keygen -t ed25519 -f "$DEPLOY_KEY" -N "" -C snippet-searcher-deploy >/dev/null
note "CI's SSH key: $DEPLOY_KEY"
for env in dev prod; do
  domain=$(domain_of "$env"); host="$VM_USER@$domain"
  say ""; say "${BOLD}$env${RESET} ($domain)"
  if ! ssh -o StrictHostKeyChecking=accept-new -o ConnectTimeout=10 "$host" true; then
    warn "can't SSH into $host"; SKIPPED+=("prepare the $env VM (run this script again)"); continue
  fi
  # shellcheck disable=SC2016 # runs on the VM
  ssh "$host" '
    set -e
    command -v docker >/dev/null || { curl -fsSL https://get.docker.com | sudo sh >/dev/null; }
    sudo usermod -aG docker "$USER"
    [ "$(sudo docker info --format "{{.Swarm.LocalNodeState}}")" = active ] || sudo docker swarm init >/dev/null
  '
  note "✓ Docker and Swarm"
  # shellcheck disable=SC2029 # the public key is expanded here, on purpose
  ssh "$host" "grep -qF snippet-searcher-deploy ~/.ssh/authorized_keys || echo '$(cat "$DEPLOY_KEY.pub")' >> ~/.ssh/authorized_keys"
  note "✓ deploy key authorized"
  AUTH0_M2M_CLIENT_SECRET=$AUTH0_M2M_CLIENT_SECRET NEW_RELIC_LICENSE_KEY=$NEW_RELIC_LICENSE_KEY \
    "$INFRA/scripts/create-secrets.sh" "$host" | sed 's/^/  /'
done
pause "Press Enter to continue"

# ── 12 ────────────────────────────────────────────────────────────────────
stage "GitHub: secrets and variables"
for repo in "${APPS[@]}"; do gh_secret "$repo" "" DEPLOY_PAT "$DEPLOY_PAT"; done
gh_var printscript-ui "" AUTH0_DOMAIN "$AUTH0_DOMAIN"
gh_var printscript-ui "" AUTH0_SPA_CLIENT_ID "$AUTH0_SPA_CLIENT_ID"
gh_var printscript-ui "" AUTH0_AUDIENCE "$AUTH0_AUDIENCE"
infra=snippet-searcher-infra
gh_secret "$infra" "" DEPLOY_PAT "$DEPLOY_PAT"
gh_var "$infra" "" AUTH0_DOMAIN "$AUTH0_DOMAIN"
gh_var "$infra" "" AUTH0_AUDIENCE "$AUTH0_AUDIENCE"
gh_var "$infra" "" AUTH0_M2M_CLIENT_ID "$AUTH0_M2M_CLIENT_ID"
gh_var "$infra" "" LETSENCRYPT_EMAIL "$LETSENCRYPT_EMAIL"
gh_var "$infra" "" NEW_RELIC_OTLP_URL "$NEW_RELIC_OTLP_URL"
gh_var "$infra" "" NEW_RELIC_ENABLED "$NEW_RELIC_ENABLED"
for env in dev prod; do
  domain=$(domain_of "$env")
  gh api -X PUT "repos/$OWNER/$infra/environments/$env" >/dev/null
  gh_var "$infra" "$env" DOMAIN "$domain"
  gh_var "$infra" "$env" SSH_USER "$VM_USER"
  gh_secret "$infra" "$env" SSH_PRIVATE_KEY "$(cat "$DEPLOY_KEY")"
  gh_secret "$infra" "$env" SSH_KNOWN_HOSTS "$(ssh-keyscan -t ed25519 "$domain" 2>/dev/null)"
done
pause "Press Enter to continue"

# ── 13 ────────────────────────────────────────────────────────────────────
stage "First push and deploy"
say "Order: first the services and the UI (their publish builds the images), then infra,"
say "whose push deploys both environments with the images already in GHCR."
say ""
if confirm "Promote dev to prod in the five repos (fast-forward only)?"; then
  for repo in "${REPOS[@]}"; do
    dir="$ROOT/$repo"
    if git -C "$dir" merge-base --is-ancestor prod dev; then
      if [[ "$(git -C "$dir" branch --show-current)" == prod ]]; then
        git -C "$dir" merge --ff-only -q dev
      else
        git -C "$dir" branch -f prod dev
      fi
      note "✓ $repo: prod = dev"
    else
      warn "$repo: prod has commits that aren't in dev; not touched"
    fi
  done
fi
if ! confirm "Push dev and prod of the four app repos?"; then
  SKIPPED+=("git push of dev and prod (services, UI, then infra)"); finish; exit 0
fi
for repo in "${APPS[@]}"; do
  git -C "$ROOT/$repo" push -u origin dev prod
  gh repo edit "$OWNER/$repo" --default-branch dev >/dev/null 2>&1 || true
done
say ""; say "Waiting for the publish runs (the first build takes a few minutes)…"

failed=0
for repo in "${APPS[@]}"; do
  for branch in dev prod; do
    # The run shows up some seconds after the push
    for _ in 1 2 3 4 5 6; do
      id=$(gh run list -R "$OWNER/$repo" --workflow publish.yml --branch "$branch" --limit 1 --json databaseId --jq '.[0].databaseId // empty')
      [[ -n "$id" ]] && break
      sleep 10
    done
    if [[ -z "$id" ]]; then warn "$repo $branch: no publish run (was the branch already up to date?)"; continue; fi
    if gh run watch "$id" -R "$OWNER/$repo" --exit-status >/dev/null; then
      note "✓ $repo $branch published"
    else
      printf '  %s✗ %s %s: publish failed%s → gh run view %s -R %s --log-failed\n' "$RED" "$repo" "$branch" "$RESET" "$id" "$OWNER/$repo"
      failed=1
    fi
  done
done
(( failed )) && warn "Some image is missing: fix it before pushing infra (its deploy would wait for it)."
if confirm "Push dev and prod of snippet-searcher-infra (deploys both environments)?"; then
  git -C "$INFRA" push -u origin dev prod
  gh repo edit "$OWNER/snippet-searcher-infra" --default-branch dev >/dev/null 2>&1 || true
  open_url "https://github.com/$OWNER/snippet-searcher-infra/actions/workflows/deploy.yml"
  say "When it's green: https://$DEV_DOMAIN and https://$PROD_DOMAIN (the certificate takes up to a minute more)."
else
  SKIPPED+=("git push of snippet-searcher-infra dev and prod")
fi
pause "Press Enter to finish"

finish
note "Values saved in $ENV_FILE (git-ignored; it has secrets: keep it or delete it)."
